import { createArenaModel } from './workspace-arena-model.js';
import { createAttributeFormat } from './persona-attributes.js';

/**
 * Markup for the live voting map. Everything here is a pure string builder over plain data, so the unit tests
 * and the browser run the same code; the browser glue that keeps the DOM current lives in workspace-arena-controls.
 * Keep the factory self-contained: it is serialized into the inline client script.
 */
export function createLiveVotingView(model: ReturnType<typeof createArenaModel>, attrs: ReturnType<typeof createAttributeFormat>) {
  type Member = Parameters<typeof model.tileVisual>[0];
  type Question = NonNullable<Parameters<typeof model.tileVisual>[1]>;
  type Board = ReturnType<typeof model.leaderboard>;
  const esc = (value: unknown): string => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]!);
  const pct = (share: number): string => `${(Math.round(share * 1000) / 10).toFixed(1)}%`;
  const BOARD_ROWS = 40;
  const number = (value: number): string => value.toLocaleString('en-US');

  const statusWord = (member: Member): string => member.status === 'queued' ? 'waiting' : member.status === 'running' ? 'thinking' : member.status === 'failed' ? 'failed' : 'voted';

  /** One sentence that names a tile for screen readers, tooltips and the detail panel. */
  function describeTile(member: Member, question: Question | undefined, segmentLabel: string): string {
    const parts = [member.label, segmentLabel, statusWord(member)];
    if (member.repeat > 1) parts.push(`repeat ${member.repeat}`);
    if (member.status === 'completed') {
      const pick = model.topPick(model.answerFor(member, question), question);
      if (pick) parts.push(question?.type === 'choice' ? `top pick ${pick.label}${pick.probability === null ? '' : ` ${Math.round(pick.probability * 100)}%`}` : pick.label);
    } else if (member.status === 'running' && member.batch) parts.push(`${member.batch.phase === 'map' ? 'reading batches' : 'combining'}, ${Math.min(member.batch.done, member.batch.total)} of ${member.batch.total} steps`);
    else if (member.status === 'failed' && member.reason) parts.push(member.reason);
    return parts.join(', ');
  }

  function tileHtml(member: Member, o: { question?: Question; colorBy: 'status' | 'pick' | 'confidence'; segmentLabel: string; selected: boolean; tabbable: boolean; pop?: boolean }): string {
    const visual = model.tileVisual(member, o.question, o.colorBy);
    let fill = '';
    if (visual.fill === 'option') fill = visual.index < model.PALETTE ? ` data-c="${visual.index}"` : ` data-c="x" style="--c:${model.optionColor(visual.index)}"`;
    else if (visual.fill === 'scale') fill = ` data-c="s" style="--v:${Math.round(visual.value * 1000) / 1000}"`;
    else if (visual.progress !== null) fill = ` style="--p:${Math.round(visual.progress * 1000) / 1000};--n:${member.batch?.total ?? 1}"`;
    const text = esc(describeTile(member, o.question, o.segmentLabel));
    return `<button type="button" class="lv-tile${o.pop ? ' is-pop' : ''}" data-act="live-member" data-key="${esc(model.memberKey(member))}" data-s="${visual.state}" data-i="${esc(model.initials(member.label))}"${fill} tabindex="${o.tabbable ? 0 : -1}" aria-pressed="${o.selected}" aria-label="${text}"></button>`;
  }

  /** Answer rows for the detail panel: every option, highest first, in the option's map colour. Labels come from the study's options when they are known. */
  function answerView(id: string, value: unknown, question: Question | undefined): string {
    const index = (optionId: string): number => question?.options.findIndex(option => option.id === optionId) ?? -1;
    const label = (optionId: string): string => question?.options.find(option => option.id === optionId)?.label ?? optionId;
    if (!value || typeof value !== 'object' || Array.isArray(value)) return `<div class="lv-answer"><strong>${esc(id)}</strong><span>${esc(JSON.stringify(value))}</span></div>`;
    const answer = value as Record<string, unknown>;
    const entries = Object.entries((answer.probabilities ?? {}) as Record<string, unknown>).map(([name, raw]) => [name, Number(raw)] as const).filter(([, probability]) => Number.isFinite(probability));
    const ordered = answer.type === 'score' ? entries.sort((a, b) => Number(a[0]) - Number(b[0])) : entries.sort((a, b) => b[1] - a[1]);
    const bars = (): string => ordered.map(([name, probability]) => {
      const percent = Math.max(0, Math.min(100, probability * 100)), at = index(name);
      const colour = answer.type === 'choice' && at >= 0 ? `;background:${model.optionColor(at)}` : '';
      const displayName = answer.type === 'score' ? (answer.legend as Record<string, string> | undefined)?.[name] ?? label(name) : label(name);
      return `<div class="lv-prob"><span>${esc(displayName)}</span><span class="lv-prob-bar"><i style="width:${percent}%${colour}"></i></span><strong>${percent.toFixed(1)}%</strong></div>`;
    }).join('');
    const sure = typeof answer.confidence === 'number' && Number.isFinite(answer.confidence) ? `<p>Stated confidence ${Math.round(Math.max(0, Math.min(1, answer.confidence)) * 100)}%</p>` : '';
    if (answer.type === 'choice') return `<div class="lv-answer"><strong>${esc(question?.label || id)}</strong><p class="lv-picked">Picked <b>${esc(label(String(answer.choice ?? 'No choice recorded')))}</b></p>${sure}${bars()}</div>`;
    if (answer.type === 'score') { const score = Number(answer.score); return `<div class="lv-answer"><strong>${esc(question?.label || id)}</strong><p class="lv-picked">Score <b>${Number.isFinite(score) ? esc(score.toFixed(2)) : 'not reported'}</b></p>${sure}${bars()}</div>`; }
    if (answer.type === 'noul') { const probability = Number(answer.noul); return `<div class="lv-answer"><strong>${esc(question?.label || id)}</strong><p class="lv-picked">${Number.isFinite(probability) ? `Yes <b>${Math.max(0, Math.min(100, probability * 100)).toFixed(1)}%</b>` : 'No probability reported'}</p></div>`; }
    return `<div class="lv-answer"><strong>${esc(id)}</strong><span>Answer format unavailable</span></div>`;
  }


  function detailHtml(member: Member | undefined, o: { question?: Question; questions: Question[]; segmentLabel: string; hidden?: boolean; persona?: { background?: string; attributes?: Record<string, unknown> } }): string {
    if (!member) return `<div class="lv-detail-empty"><strong>Pick a tile</strong><p>Hover to see who voted and what they picked. Click, or move with the arrow keys and press Enter, to read their full answer.</p></div>`;
    const initial = esc(member.label.slice(0, 1).toUpperCase());
    const close = '<button type="button" class="lv-detail-close" data-act="live-deselect">Back to ranking</button>';
    if (o.hidden) return `${close}<div class="lv-detail-mark" aria-hidden="true">·</div><h3>Not revealed yet</h3><p>Play the replay forward to see this synthetic profile’s saved result.</p>`;
    const batch = member.batch && member.status === 'running' ? `<p>${member.batch.phase === 'map' ? 'Reading the responses in batches' : 'Combining the batch verdicts'}: ${Math.min(member.batch.done, member.batch.total)} of ${member.batch.total} steps done.</p>` : '';
    const answers = member.answers ? Object.entries(member.answers).map(([id, answer]) => answerView(id, answer, o.questions.find(item => item.id === id) ?? (id === o.question?.id ? o.question : undefined))).join('') : '<p class="lv-muted">No model answer recorded yet.</p>';
    const fields = Object.entries(o.persona?.attributes ?? {});
    const profile = o.persona && (o.persona.background || fields.length) ? `<div class="lv-profile"><h4>Who they are</h4>${o.persona.background ? `<p>${esc(o.persona.background)}</p>` : ''}${fields.length ? `<dl>${fields.map(([key, value]) => `<div><dt>${esc(attrs.label(key))}</dt><dd>${attrs.html(value, key)}</dd></div>`).join('')}</dl>` : ''}</div>` : '';
    return `${close}<div class="lv-detail-mark" aria-hidden="true">${initial}</div><h3>${esc(member.label)}</h3><p>${esc(o.segmentLabel)} · age ${esc(member.age)} · ${esc(statusWord(member))}${member.repeat > 1 ? ` · repeat ${member.repeat}` : ''}</p>${member.model ? `<p>Model: ${esc(member.model)}${member.cacheHit ? ' · cached result' : ''}</p>` : ''}${batch}${member.reason ? `<p role="alert">${esc(member.reason)}</p>` : ''}<div class="lv-answers"><h4>Model answers</h4>${answers}<p class="lv-muted">The model returns a share for every option; it does not return written reasoning.</p></div>${profile}<p class="lv-synthetic">Synthetic profile; model output is not observed human behavior.</p>`;
  }

  function tooltipHtml(member: Member, o: { question?: Question; segmentLabel: string }): string {
    const visual = model.tileVisual(member, o.question, 'pick');
    const pick = member.status === 'completed' ? model.topPick(model.answerFor(member, o.question), o.question) : undefined;
    const swatch = pick && visual.fill === 'option' ? `<i class="lv-tip-swatch" style="background:${model.optionColor(visual.index)}"></i>` : '';
    const line = member.status === 'completed' ? (pick ? `${swatch}${esc(pick.label)}${pick.probability !== null && o.question?.type === 'choice' ? ` · ${Math.round(pick.probability * 100)}%` : ''}` : 'No answer recorded') : member.status === 'failed' ? 'Evaluation failed' : member.status === 'running' ? (member.batch ? `Thinking · step ${Math.min(member.batch.done, member.batch.total)} of ${member.batch.total}` : 'Thinking…') : 'Waiting for a turn';
    return `<strong>${esc(member.label)}</strong><span>${esc(o.segmentLabel)}${member.repeat > 1 ? ` · repeat ${member.repeat}` : ''}</span><span class="lv-tip-line">${line}</span>`;
  }

  /** The slot every leaderboard row belongs in: one row per rank, so rows can never share or skip a position. */
  function rowSlots(rows: { id: string }[], leader: string | null): { id: string; rank: number; slot: number; hidden: boolean; leader: boolean }[] {
    return rows.map((row, rank) => ({ id: row.id, rank, slot: Math.min(rank, BOARD_ROWS), hidden: rank >= BOARD_ROWS, leader: leader === row.id }));
  }

  function boardRows(board: Board, question: Question | undefined, colorBy: string): string {
    if (!question) return '<li class="lv-row-empty">This step has no question to tally.</li>';
    const rows = question.type === 'score' || question.type === 'noul' ? board.rows : board.rows;
    const max = Math.max(0.0001, ...rows.map(row => row.share));
    const seeded = rows.length ? rows : question.options.map((option, index) => ({ id: option.id, label: option.label, index, share: 0 }));
    return seeded.map((row, rank) => {
      const color = question.type === 'choice' ? model.optionColor(row.index) : `color-mix(in srgb, var(--lv-seq-hi) ${Math.round((question.options.length > 1 ? row.index / (question.options.length - 1) : 1) * 100)}%, var(--lv-seq-lo))`;
      return `<li class="lv-row" data-opt="${esc(row.id)}" data-leader="${board.leader === row.id}" data-hidden="${rank >= BOARD_ROWS}" data-rank="${rank}" data-p="${row.index >= model.PALETTE ? 'x' : row.index >= 7 ? row.index % 2 ? 'dots' : 'stripes' : 'plain'}" style="--rank:${Math.min(rank, BOARD_ROWS)};--w:${Math.round(row.share / max * 1000) / 1000};--c:${color}"><span class="lv-rank" aria-hidden="true">${rank + 1}</span><span class="lv-swatch" aria-hidden="true"></span><span class="lv-name">${esc(row.label)}</span><span class="lv-bar" aria-hidden="true"><i></i></span><strong class="lv-pct">${pct(row.share)}</strong></li>`;
    }).join('');
  }

  function boardHtml(board: Board, question: Question | undefined, colorBy: string, final = false): string {
    const shown = Math.min(BOARD_ROWS, Math.max(1, question?.options.length ?? 1));
    const more = question && question.options.length > BOARD_ROWS ? `<p class="lv-more">${question.options.length - BOARD_ROWS} lower-ranked options not shown.</p>` : '';
    const heading = question?.type === 'score' ? 'Score distribution' : question?.type === 'noul' ? 'Likelihood of yes' : final ? 'Final ranking' : 'Leaderboard';
    const sub = question?.type === 'score' && board.mean !== null ? `Mean score ${Math.round(board.mean * 100) / 100}` : board.evaluated ? `${board.weighted ? 'Weighted share' : 'Equal-weight share'} of ${number(board.evaluated)} evaluated` : 'Fills in as members vote';
    return `<div class="lv-board-head"><h3>${heading}</h3><span data-lv="board-sub">${esc(sub)}</span></div><ol class="lv-rows" style="--rows:${shown}">${boardRows(board, question, colorBy)}</ol>${more}`;
  }

  /** Commentary lines, newest first. Each line is already stamped by the caller (clock time live, vote count in a replay). */
  function newsItems(lines: { text: string; time: string; kind: string }[]): string {
    return lines.length ? lines.map(line => `<li data-kind="${esc(line.kind)}"><time>${esc(line.time)}</time><span>${esc(line.text)}</span></li>`).join('') : '<li class="lv-news-empty"><span>Lines appear here as results come in.</span></li>';
  }
  function newsHtml(lines: { text: string; time: string; kind: string }[]): string {
    return `<section class="lv-news" aria-label="Commentary"><h3>Commentary</h3><ol data-lv="news" aria-live="off">${newsItems(lines.slice(0, 4))}</ol></section>`;
  }

  /** The finished run in place: a one-line factual summary plus each segment's top three options. */
  function resultsHtml(results: { summary: string; cost?: { amount: string; detail: string } | null; segments: { id: string; label: string; evaluated: number; top: { id: string; label: string; share: number }[] }[] }, question: Question | undefined): string {
    const rows = results.segments.map(segment => `<li class="lv-seg-row"><div class="lv-seg-head"><strong title="${esc(segment.label)}">${esc(segment.label)}</strong><span>${number(segment.evaluated)} voted</span></div><ol>${segment.top.map((entry, rank) => `<li><i class="lv-swatch" data-p="${(question?.options.findIndex(option => option.id === entry.id) ?? 0) >= 7 ? 'dot' : 'plain'}" style="--c:${model.optionColor(question?.options.findIndex(option => option.id === entry.id) ?? 0)}" aria-hidden="true"></i><span class="lv-seg-name">${rank + 1}. ${esc(entry.label)}</span><b>${pct(entry.share)}</b></li>`).join('')}</ol></li>`).join('');
    const cost = results.cost ? `<div class="lv-cost" title="Estimated from the tokens this run spent; saved answers reused from cache are free. Per-step cost is in the report."><span>Study cost</span><strong>${esc(results.cost.amount)}</strong><small>${esc(results.cost.detail)}</small></div>` : '';
    return `<section class="lv-results" aria-label="Results"><h3>Results</h3><p class="lv-summary">${esc(results.summary)}</p>${rows ? `<ul class="lv-segs" aria-label="Top three options per segment">${rows}</ul>` : ''}${cost}</section>`;
  }

  function legendHtml(colorBy: string, question: Question | undefined, stats: { queued: number; running: number; done: number; failed: number }): string {
    if (colorBy === 'status') return ['queued|Waiting|queued', 'running|Thinking|running', 'done|Voted|done', 'failed|Failed|failed'].map(entry => { const [state, label, key] = entry.split('|'); return `<span class="lv-legend-item"><i class="lv-tile-key" data-s="${state}" aria-hidden="true"></i>${label} <b data-lv="count-${key}">${number(stats[key as 'queued'])}</b></span>`; }).join('');
    if (colorBy === 'confidence') return `<span class="lv-legend-item">Unsure</span><i class="lv-gradient" aria-hidden="true"></i><span class="lv-legend-item">Certain</span><span class="lv-legend-item lv-legend-quiet">Top option’s probability. Grey tiles have not voted.</span>`;
    if (question && question.type !== 'choice') return `<span class="lv-legend-item">${question.type === 'noul' ? 'Unlikely' : 'Low'}</span><i class="lv-gradient" aria-hidden="true"></i><span class="lv-legend-item">${question.type === 'noul' ? 'Likely' : 'High'}</span>`;
    return `<span class="lv-legend-item lv-legend-quiet">Tile colour is the member’s top pick, matching the leaderboard. Grey tiles have not voted.</span>`;
  }

  function statsHtml(stats: { done: number; total: number; failed: number; running: number; rateText: string; leftText: string }, live: boolean, replaying = false, cost: { amount: string; detail: string } | null = null): string {
    const finished = stats.done + stats.failed;
    const percent = stats.total ? Math.round(finished / stats.total * 1000) / 10 : 0;
    const chip = (key: string, label: string, value: string): string => `<div class="lv-stat"><span>${label}</span><strong data-lv="${key}">${value}</strong></div>`;
    return `<div class="lv-progress" role="progressbar" aria-label="Evaluations finished" aria-valuemin="0" aria-valuemax="${stats.total}" aria-valuenow="${finished}"><i data-lv="bar" style="--f:${percent / 100}"></i></div><div class="lv-stats">${chip('done', replaying ? 'Revealed' : 'Evaluated', `${number(finished)} / ${number(stats.total)}`)}${chip('running', 'Thinking', number(stats.running))}${chip('failed', 'Failed', number(stats.failed))}${live ? chip('rate', 'Speed', stats.rateText) + chip('left', 'Time left', stats.leftText) : ''}${!live && cost ? chip('cost', 'Study cost', esc(cost.amount)) : ''}</div>`;
  }

  function segmented(action: string, label: string, options: [string, string][], value: string): string {
    return `<div class="lv-field" role="group" aria-label="${esc(label)}"><span class="lv-field-label">${esc(label)}</span><div class="lv-seg">${options.map(([key, text]) => `<button type="button" data-act="${action}" data-value="${esc(key)}" aria-pressed="${key === value}">${esc(text)}</button>`).join('')}</div></div>`;
  }

  function groupsHtml(input: any): string {
    const byKey = new Map<string, Member>(input.members.map((member: Member) => [model.memberKey(member), member]));
    return input.groups.map((group: { id: string; label: string; keys: string[] }, index: number) => {
      const tiles = group.keys.map(key => {
        const member = byKey.get(key)!;
        return tileHtml(member, { question: input.question, colorBy: input.colorBy, segmentLabel: input.segmentLabels[member.segment] || member.segment, selected: key === input.selectedKey, tabbable: key === input.tabKey });
      }).join('');
      return `<section class="lv-group" data-group="${esc(group.id)}" aria-label="${esc(group.label)}, ${number(group.keys.length)} members"><h3 title="${esc(group.label)}"><span>${esc(group.label)}</span><b>${number(group.keys.length)}</b></h3><div class="lv-tiles" style="--cols:${input.layout.columns[index] ?? 1}">${tiles}</div></section>`;
    }).join('');
  }

  function replayControls(replay: any): string {
    const speeds = [1, 2, 4, 8];
    return `<div class="lv-replay" role="group" aria-label="Replay controls"><div class="lv-replay-actions"><button type="button" class="lv-play" data-act="arena-play" aria-pressed="${!!replay.playing}">${replay.playing ? 'Pause' : 'Play'}</button><button type="button" data-act="arena-step" aria-label="Reveal next member">Step</button><button type="button" data-act="arena-reset" aria-label="Restart replay">Restart</button><button type="button" data-act="arena-live">Show all</button></div><div class="lv-seg" role="group" aria-label="Replay speed">${speeds.map(speed => `<button type="button" data-act="arena-speed" data-speed="${speed}" aria-pressed="${replay.speed === speed}">${speed}×</button>`).join('')}</div><label class="lv-scrub"><span data-lv="scrub-text">${number(Math.floor(replay.cursor))} of ${number(replay.total)} ${replay.total === 1 ? 'member' : 'members'} revealed</span><input type="range" min="0" max="${replay.total}" step="any" value="${replay.cursor}" data-arena-scrub aria-label="Replay position"></label></div>`;
  }

  function stageNav(input: any): string {
    // The study graph, when the caller could build it: each step with what it reads and what it gives out.
    if (input.graphHtml) return `<div class="lv-graph">${segmented('lv-steps', 'Steps', [['summary', 'Summary'], ['fields', 'Inputs & outputs']], input.stepsView === 'fields' ? 'fields' : 'summary')}${input.graphHtml}</div>`;
    if (input.stages.length < 2) return '';
    return `<nav class="lv-stages" aria-label="Study steps">${input.stages.map((stage: any) => {
      const dependencies = (stage.dependsOn || []).map((id: string) => input.stages.find((candidate: any) => candidate.id === id)?.label || id);
      const detail = `${stage.kind || 'step'} · ${stage.status || 'pending'} · ${dependencies.length ? `after ${dependencies.join(', ')}` : 'first step'}`;
      return `<button type="button" data-act="live-stage" data-stage="${esc(stage.id)}" aria-pressed="${stage.id === input.stageId}" data-stage-state="${esc(stage.status)}" title="${esc(detail)}" aria-label="${esc(`${stage.label}, ${detail}`)}"><i aria-hidden="true"></i><span>${esc(stage.label)}</span></button>`;
    }).join('')}</nav>`;
  }

  /** A step with no audience (a Final answer, or combined answers): what it settled on and what it read, instead of an empty tile map. */
  function outcomeHtml(input: any): string {
    const outcome = input.outcome, pct = (share: number) => `${Math.round(share * 100)}%`;
    const how = input.outcomeKind === 'choose' ? 'Jev read the steps below and answered once. No audience.' : input.outcomeKind === 'decision' ? 'Took the top option of the step below. No Jev request.' : 'Weighted the connected answers together. No Jev request.';
    const answers = (outcome.answers || []).map((answer: any) => {
      const top = answer.type === 'score' && answer.mean !== undefined ? `Mean score ${answer.mean.toFixed(2)}` : answer.type === 'noul' && answer.likelihood !== undefined ? `${pct(answer.likelihood)} likely yes` : answer.winner || 'No answer';
      const bars = (answer.options || []).slice(0, 8).map((option: any) => `<li class="lv-outcome-bar" data-lead="${option.label === answer.winner}"><span class="lv-outcome-label">${esc(option.label)}</span><span class="lv-outcome-track" aria-hidden="true"><i style="width:${Math.max(0, Math.min(100, option.share * 100)).toFixed(1)}%"></i></span><span class="lv-outcome-share">${pct(option.share)}</span></li>`).join('');
      return `<div class="lv-outcome-answer">${(outcome.answers.length > 1 ? `<h3>${esc(answer.label)}</h3>` : '')}<p class="lv-outcome-winner">${esc(top)}</p>${bars ? `<ol class="lv-outcome-bars" aria-label="How likely each option is">${bars}</ol>` : ''}</div>`;
    }).join('');
    const reads = (outcome.reads || []).length ? `<div class="lv-outcome-reads"><h3>Read</h3><ul>${outcome.reads.map((line: string) => `<li>${esc(line)}</li>`).join('')}</ul>${outcome.note ? `<p>${esc(outcome.note)}.</p>` : ''}</div>` : '';
    return `<div class="lv-outcome"><p class="lv-outcome-how">${esc(how)}</p>${answers}${reads}</div>`;
  }

  /** The whole view for one step of one run. */
  function html(input: any): string {
    const live = input.status === 'running';
    const shown = !input.members.length && !!input.outcome;
    const kicker = shown ? 'Step result' : live ? 'Live voting' : 'Voting replay';
    const members: Member[] = input.members;
    const note = live
      ? 'Each tile is one synthetic member evaluation; repeats are separate tiles. Tiles count evaluations, not audience share.'
      : input.replay ? `Replay reveals the saved synthetic judgments ${input.replay.ordered ? 'in the order their evaluations finished' : 'in saved order'}; its speed is illustrative, not the real timing. Tiles count evaluations, not audience share.` : 'Each tile is one synthetic member evaluation. Tiles count evaluations, not audience share.';
    const empty = !members.length;
    const groupOptions: [string, string][] = input.groupOptions;
    const controls = empty ? '' : `<div class="lv-controls">${segmented('lv-color', 'Colour by', [['status', 'Status'], ['pick', input.question?.type === 'choice' ? 'Top pick' : 'Result'], ['confidence', 'Confidence']], input.colorBy)}<label class="lv-field"><span class="lv-field-label">Group by</span><select data-lv-group aria-label="Group by">${groupOptions.map(([value, text]) => `<option value="${esc(value)}"${value === input.groupBy ? ' selected' : ''}>${esc(text)}</option>`).join('')}</select></label>${input.questions.length > 1 ? `<label class="lv-field"><span class="lv-field-label">Question</span><select data-lv-question aria-label="Question">${input.questions.map((question: Question) => `<option value="${esc(question.id)}"${question.id === input.question?.id ? ' selected' : ''}>${esc(question.label)}</option>`).join('')}</select></label>` : ''}${segmented('lv-zoom', 'Zoom', [['fit', 'Fit all'], ['1', '1:1'], ['2', 'Large']], input.zoom)}</div>`;
    const done = !live && !input.replay && !!input.results?.summary;
    const player = live || empty ? '' : input.replay ? replayControls(input.replay) : '<div class="lv-replay lv-replay-start"><button type="button" class="lv-play" data-act="arena-replay">Replay voting</button></div>';
    const body = shown ? outcomeHtml(input) : empty
      ? `<div class="lv-empty"><strong>${esc(input.title)}</strong><span>${esc(input.emptyReason)}</span></div>`
      : `<div class="lv-body"><div class="lv-stage"><div class="lv-map" data-zoom="${esc(input.zoom)}" aria-label="Member evaluations grouped by ${esc(groupOptions.find(([value]) => value === input.groupBy)?.[1] || 'segment')}"><div class="lv-groups" data-big="${input.layout.tile >= 30}" style="--tile:${input.layout.tile}px">${groupsHtml(input)}</div></div><div class="lv-under"><div class="lv-legend" data-lv="legend">${legendHtml(input.colorBy, input.question, input.stats)}</div>${player}</div></div><aside class="lv-side"><section class="lv-board" aria-label="${input.question?.type === 'choice' ? 'Leaderboard' : 'Tally'} for ${esc(input.question?.label || 'the question')}"><p class="lv-board-question">${esc(input.question?.label || '')}</p><div data-lv="board">${boardHtml(input.board, input.question, input.colorBy, done)}</div></section>${done ? resultsHtml(input.results, input.question) : input.question?.type === 'choice' ? newsHtml(input.news || []) : ''}<section class="lv-detail" aria-live="polite" data-lv="detail" data-has="${!!input.selected}">${detailHtml(input.selected, { question: input.question, questions: input.questions, segmentLabel: input.selected ? input.segmentLabels[input.selected.segment] || input.selected.segment : '', hidden: input.selectedHidden, persona: input.selectedPersona })}</section><p class="lv-note">${esc(note)}</p></aside></div>`;
    const full = !!input.full;
    const actions = full ? `<div class="lv-actions"><button type="button" class="lv-back" data-act="${esc(input.backAct || 'live-back')}"${input.backId ? ` data-id="${esc(input.backId)}"` : ''}>${esc(input.backLabel || 'Back to study')}<kbd aria-hidden="true">Esc</kbd></button>${input.reportUrl ? `<a class="lv-report" href="${esc(input.reportUrl)}" target="_blank" rel="noopener noreferrer" aria-label="Open report (new tab)">Open report</a>` : ''}</div>` : '';
    const heading = full ? `<h1 tabindex="-1">${esc(input.studyTitle || input.title)}</h1>` : `<h2>${esc(input.title)}</h2>`;
    return `<section class="live-voting" data-run="${esc(input.runId)}" data-stage="${esc(input.stageId)}" data-mode="${live ? 'live' : input.replay ? 'replay' : 'done'}" data-full="${full}" aria-label="${kicker}"><header class="lv-head"><div class="lv-title"><p class="lv-kicker">${kicker}${full && input.studyTitle ? ` · ${esc(input.title)}` : ''}<span class="lv-message" data-lv="message">${esc(input.message || '')}</span></p>${heading}</div><div class="lv-strip" role="status" aria-label="Voting progress" data-lv="strip">${shown ? '' : statsHtml({ ...input.stats, total: input.stats.total }, live, !!input.replay, input.results?.cost ?? null)}</div>${actions}</header><div class="lv-toolbar">${stageNav(input)}${controls}</div>${body}${shown ? '<p class="lv-note">Model estimates, not human responses.</p>' : empty ? `<p class="lv-note">${esc(note)}</p>` : ''}<div class="lv-tip" role="tooltip" hidden></div></section>`;
  }

  return { esc, describeTile, tileHtml, detailHtml, tooltipHtml, boardHtml, boardRows, rowSlots, newsHtml, newsItems, resultsHtml, legendHtml, statsHtml, groupsHtml, html, BOARD_ROWS };
}

/** Browser build of the model and view: one `window.liveVoting` the workspace script drives. */
export const WORKSPACE_LIVE_UI_CLIENT = `window.liveVoting = (() => { const __name = (value) => value; const model = (${createArenaModel.toString()})(); const attrs = (${createAttributeFormat.toString()})(); return { model, view: (${createLiveVotingView.toString()})(model, attrs) }; })();`;

/** Fourteen muted option colours (OKLCH chroma ≤ 0.10), the dark set being the light set 0.1 lighter so an option keeps its hue across themes. Searched so every pair stays apart under a deuteranopia simulation (CIE76 ΔE ≥ 16 in both themes); slots 7 and up add a stripe or dot pattern as a second cue. */
export const PALETTE_LIGHT = ['#a15652', '#7c9bda', '#d4c174', '#70d6c3', '#54526b', '#6f5d00', '#38538d', '#cfa38d', '#a8779c', '#9cbbdd', '#6a4c4f', '#b57a47', '#8b65a2', '#b48388'];
export const PALETTE_DARK = ['#c2736e', '#9abafb', '#f5e293', '#92f8e4', '#706e88', '#8c7a2b', '#5370ac', '#f0c3ac', '#c895bb', '#bcdbff', '#87686b', '#d69865', '#aa83c2', '#d4a2a7'];
const paletteVars = (colors: string[]): string => colors.map((color, index) => `--lv-c${index}:${color}`).join(';');
const paletteSelectors = (colors: string[]): string => colors.map((_, index) => `.lv-tile[data-c="${index}"]{--c:var(--lv-c${index})}`).join('');
const patternSelectors = (kind: 'stripes' | 'dots'): string => Array.from({ length: 14 }, (_, index) => index).filter(index => index >= 7 && (index % 2 === 1) === (kind === 'stripes')).map(index => `.lv-tile[data-s=done][data-c="${index}"]`).join(',');

